    const mk = $('Match Kalshi Teams').first().json;
    const ke = mk.kalshi_edge;
    if (mk.kalshi_available && ke) {
      kalshiStr = away + ': ' + ke.away_implied_pct + '% implied win | ' +
                  home + ': ' + ke.home_implied_pct + '% implied win | ' +
                  'Volume: $' + ke.volume;
    }
  } catch(e) {}

  // Sportsbook odds detail (matches MLB's handling — full board, may not be the matched game)
  let oddsData = '';
  try { oddsData = JSON.stringify($('Get CFB Odds').first().json).slice(0, 1500); } catch(e) {}

  return 'You are Bobby Vegas — a sharp, witty AI sports betting advisor.\n\n' +
    'The user requested: ' + away + ' vs ' + home + '\n\n' +
    'CRITICAL INSTRUCTIONS:\n' +
    '- ONLY analyze the game: ' + away + ' vs ' + home + ' — do NOT reference any other game\n' +
